import sys

def rejected(reason, detail=''):
    print('{"code":"E_INPUT","reason":"%s"%s}' % (reason, detail), file=sys.stderr)
    raise SystemExit(1)

def levels(args):
    values = []
    for pos, text in enumerate(args, 1):
        digits = text[1:] if text.startswith('-') else text
        if not digits.isascii() or not digits.isdecimal():
            rejected('expected_i64', ',"argument":%d' % pos)
        if len(digits) > 19:
            digits = digits.lstrip('0') or '0'
            if len(digits) > 19:
                rejected('expected_i64', ',"argument":%d' % pos)
            value = -int(digits) if text.startswith('-') else int(digits)
        else:
            value = int(text)
        if not -(1<<63) <= value < (1<<63):
            rejected('expected_i64', ',"argument":%d' % pos)
        values.append(value)
    return values

def motions(args):
    values = []
    for pos, text in enumerate(args, 1):
        if text not in ('true', 'false'):
            rejected('expected_bool', ',"argument":%d' % pos)
        values.append(text == 'true')
    return values

def pump(events):
    on = False
    for level in events:
        if level < 20:
            on = True
        elif level > 80:
            on = False
        yield on

def light(events):
    on, missed = False, 0
    for motion in events:
        if motion:
            on, missed = True, 0
        elif missed == 0:
            missed = 1
        else:
            on, missed = False, 2
        yield on

if __name__ == '__main__':
    which = sys.argv[1]
    args = sys.argv[2:]
    if len(args) > 4096:
        rejected('list_too_long', ',"limit":4096')
    result = pump(levels(args)) if which == 'pump' else light(motions(args))
    print('[' + ','.join('true' if on else 'false' for on in result) + ']')

