        summary={k:stats([r[k] for r in measured]) for k in ['native_ns','python_ns','ratio']}
        reports[name]['sizes'][n]={'rows':rows,'summary':summary}
        print(name,n,{k:round(v['median'],2) for k,v in summary.items()},flush=True)
out=dict(cpu=2,pinned=sorted(os.sched_getaffinity(0)),python=platform.python_version(),platform=platform.platform(),cpu_model=next(l.split(':',1)[1].strip() for l in Path('/proc/cpuinfo').read_text().splitlines() if l.startswith('model name')),reports=reports)
(w/'timings.json').write_text(json.dumps(out,indent=2)+'\n')
